/* ── Configuración editable ──────────────────────────────────────
   VALOR_HORA es el único número de negocio que vive en n8n. Las horas
   de cada módulo viven en Notion y se editan allá, no acá.          */
const VALOR_HORA = 45000;

/* id que manda la web  →  valor exacto de la columna "Servicio" en Notion.
   Para sumar un servicio nuevo: agregá la fila acá y en la web.       */
const SERVICIOS = {
  'web-comercial':    'Web comercial',
  'automatizaciones': 'Automatizaciones',
  'dashboards':       'Dashboards y herramientas internas',
  'ia-aplicada':      'IA aplicada'
};

const MAX_CANTIDAD = 20;   // techo por módulo, para que nadie pida 9999

function txt(p) {
  if (!p) return '';
  const arr = p.title || p.rich_text;
  return Array.isArray(arr) ? arr.map(t => t.plain_text).join('') : '';
}
const sel = (p) => (p && p.select ? p.select.name : '');
const num = (p) => (p && typeof p.number === 'number' ? p.number : 0);
const chk = (p) => !!(p && p.checkbox);

/* Convierte las filas crudas de Notion en los módulos de un servicio. */
function modulosDe(results, servicioNombre) {
  return (results || [])
    .map((r) => {
      const p = r.properties || {};
      return {
        id:          String(r.id).replace(/-/g, ''),
        nombre:      txt(p['Módulo']),
        descripcion: txt(p['Descripción']),
        pregunta:    txt(p['Pregunta del formulario']),
        categoria:   sel(p['Categoría']),
        servicio:    sel(p['Servicio']),
        seAplica:    sel(p['Se aplica']),
        horas:       num(p['Horas']),
        activo:      chk(p['Activo'])
      };
    })
    .filter((m) => m.activo && m.servicio === servicioNombre && m.horas > 0)
    /* Las preguntas entre paréntesis no se le muestran al cliente:
         · Base  → se incluye siempre, no se pregunta
         · resto → no se cotiza desde la web (ej. "Ronda de revisión extra") */
    .filter((m) => m.categoria === 'Base' || !/^\s*\(/.test(m.pregunta))
    .map((m) => Object.assign({}, m, {
      control: m.categoria === 'Base'
        ? 'incluido'
        : (m.seAplica === 'Una vez' ? 'toggle' : 'cantidad')
    }))
    .sort((a, b) => {
      if (a.categoria === 'Base') return -1;
      if (b.categoria === 'Base') return 1;
      return a.nombre.localeCompare(b.nombre, 'es');
    });
}

/* Resuelve el precio. NUNCA confía en lo que manda el navegador:
     · los módulos Base entran siempre en 1
     · las cantidades se recortan a [0, MAX_CANTIDAD]
     · los ids desconocidos se ignoran                                */
function cotizar(modulos, seleccion) {
  const desglose = [];
  let horas = 0;

  for (const m of modulos) {
    let cant;
    if (m.control === 'incluido') {
      cant = 1;
    } else {
      const pedido = Number((seleccion || {})[m.id]);
      cant = Number.isFinite(pedido) ? Math.floor(pedido) : 0;
      cant = Math.max(0, Math.min(MAX_CANTIDAD, cant));
      if (m.control === 'toggle') cant = cant > 0 ? 1 : 0;
    }
    if (cant === 0) continue;

    const h = m.horas * cant;
    horas += h;
    desglose.push({
      id: m.id,
      modulo: m.nombre,
      descripcion: m.descripcion,
      categoria: m.categoria,
      cantidad: cant,
      horas: h,
      subtotal: h * VALOR_HORA
    });
  }

  return { horas: horas, valor_hora: VALOR_HORA, total: horas * VALOR_HORA, desglose: desglose };
}

/* ══ Arma la propuesta completa para el PDF y el email ════════════ */
const body = $('Webhook propuesta').first().json.body || {};
const c = body.contacto || {};

const nombre = String(c.nombre || '').trim().slice(0, 120);
const email  = String(c.email  || '').trim().slice(0, 160);

/* Validación mínima: sin email no hay a dónde mandar nada. */
if (!nombre || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
  throw new Error('Contacto inválido: falta nombre o el email no es válido');
}

const servicioId = String(body.servicio || '');
const servicioNombre = SERVICIOS[servicioId];
if (!servicioNombre) throw new Error('Servicio desconocido: ' + servicioId);

const modulos = modulosDe($input.first().json.results, servicioNombre);
const r = cotizar(modulos, body.seleccion);
if (!r.desglose.length) throw new Error('La selección quedó vacía');

/* Número de propuesta: CL-<MMYY>-<4 dígitos del timestamp>. Legible y
   suficientemente único para el volumen que manejamos. */
const ahora = new Date();
const dosD = (n) => String(n).padStart(2, '0');
const numero = 'CL-' + dosD(ahora.getMonth() + 1) + dosD(ahora.getFullYear() % 100)
             + '-' + String(Date.now()).slice(-4);

const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio',
               'agosto','septiembre','octubre','noviembre','diciembre'];
const fecha = ahora.getDate() + ' de ' + MESES[ahora.getMonth()] + ' de ' + ahora.getFullYear();

return [{
  json: {
    numero: numero,
    fecha: fecha,
    validez: '15 días',
    servicio: servicioNombre,
    servicio_id: servicioId,
    cliente: {
      nombre: nombre,
      email: email,
      empresa:  String(c.empresa  || '').trim().slice(0, 160),
      telefono: String(c.telefono || '').trim().slice(0, 40)
    },
    mensaje: String(c.mensaje || '').trim().slice(0, 1200),
    modulos: r.desglose,
    horas: r.horas,
    valor_hora: r.valor_hora,
    total: r.total,
    total_formateado: '$ ' + r.total.toLocaleString('es-AR', { maximumFractionDigits: 0 }),
    calendar: 'https://calendar.app.google/YrXbTqH8iREgLShf6',
    origen: String(body.origen || '')
  }
}];

/* ══ Punto único de salida ════════════════════════════════════════
   Todo lo que se le manda al cliente sale de acá. Hoy hay una sola
   rama (Email). En FASE 2, el nodo de WhatsApp Cloud API se cuelga
   de ESTE MISMO nodo como segunda rama — no hay que tocar nada de
   lo de arriba: el PDF ya viene generado y los datos ya están acá. */
const p = $('Armar propuesta').first().json;

return [{
  json: {
    nombre: p.cliente.nombre,
    email: p.cliente.email,
    telefono: p.cliente.telefono,
    servicio: p.servicio,
    numero: p.numero,
    total_formateado: p.total_formateado,
    horas: p.horas,
    calendar: p.calendar,
    /* nombre del adjunto, usado por el nodo de email */
    archivo: 'Propuesta-ChichaLabs-' + p.numero + '.pdf'
  },
  binary: $input.first().binary   // el PDF que devolvió el endpoint
}];
